export const checkConnection = async () => {
  try {
    // Verificamos a tabela 'profiles' com um timeout implícito ou limite curto
    // Se o banco estiver "acordando", essa query pode demorar um pouco mais
    const { error, data } = await supabase
      .from('profiles')
