/**
 * Verifica se um erro é relacionado a falha de rede (projeto pausado ou sem internet)
 */
export const isNetworkError = (error: any) => {
  if (!error) return false;
  const message = error.message?.toLowerCase() || "";
  return message.includes("failed to fetch") || 
         message.includes("network error") || 
         message.includes("load failed") ||
         message.includes("dns_probe_finished_nxdomain");
};

// Helper to check connection status
export const checkConnection = async () => {
  try {
    // Tentamos uma query simples na tabela de perfis
    const { error } = await supabase
      .from('profiles')
      .select('id')
      .limit(1)
      .maybeSingle();

    if (error) {
      if (isNetworkError(error)) {
        return { ok: false, type: 'NETWORK' as const, message: error.message };
      }
      // Se o erro for "relação não existe", as tabelas não foram criadas
      if (error.code === 'PGRST116' || error.message.includes('relation "public.profiles" does not exist')) {
          return { ok: false, type: 'SQL' as const, message: "Tabelas não encontradas." };
      }
      return { ok: false, type: 'OTHER' as const, message: error.message };
    }
    return { ok: true, type: 'SUCCESS' as const };
  } catch (e: any) {
    if (isNetworkError(e)) {
        return { ok: false, type: 'NETWORK' as const, message: e.message };
    }
    return { ok: false, type: 'OTHER' as const, message: e.message };
  }
};

