  const [showConfirmNewPassword, setShowConfirmNewPassword] = useState(false);
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  const verifyConnection = async () => {
    setIsRetrying(true);
    const result = await checkConnection();
    if (result.ok) setConnStatus('ONLINE');
    else if (result.type === 'NETWORK') setConnStatus('OFFLINE_NETWORK');
    else if (result.type === 'SQL') setConnStatus('OFFLINE_SQL');
    else setConnStatus('OFFLINE_OTHER');
    setIsRetrying(false);
  };

  useEffect(() => {
    verifyConnection();

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
  };

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
        setPasswordMsg({ text: "A senha deve ter no mínimo 6 caracteres.", type: 'error' });
        return;
    }
    if (newPassword !== confirmPassword) {
        setPasswordMsg({ text: "As senhas não conferem.", type: 'error' });
