-- 4. POLÍTICAS DE ACESSO PÚBLICO (Simplificado para o seu uso)
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir tudo" ON public.materials FOR ALL USING (true) WITH CHECK (true);
