type ConnectionStatus = 'LOADING' | 'ONLINE' | 'OFFLINE_NETWORK' | 'OFFLINE_SQL' | 'OFFLINE_OTHER';

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [connStatus, setConnStatus] = useState<ConnectionStatus>('LOADING');
  const [isRetrying, setIsRetrying] = useState(false);

  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState(''); 
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  const verifyConnection = async () => {
    setIsRetrying(true);
    const result = await checkConnection();
    if (result.ok) setConnStatus('ONLINE');
    else if (result.type === 'NETWORK') setConnStatus('OFFLINE_NETWORK');
    else if (result.type === 'SQL') setConnStatus('OFFLINE_SQL');
    else setConnStatus('OFFLINE_OTHER');
    setIsRetrying(false);
  };

  useEffect(() => {
    verifyConnection();
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });
    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
  };

  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex flex-col items-center justify-center gap-4">
