/**
 * Converte um objeto de erro do Supabase em uma string legível
 */
export const getErrorMessage = (error: any): string => {
  if (!error) return "Erro desconhecido";
  if (typeof error === 'string') return error;
  return error.message || error.details || JSON.stringify(error);
};

/**
 * Verifica detalhadamente o tipo de erro de rede
 */
export const isNetworkError = (error: any) => {
  if (!error) return false;
  const msg = getErrorMessage(error).toLowerCase();
  const code = error.code || "";

  // Apenas erros que indicam que o browser não conseguiu nem chegar no servidor
  return msg.includes("failed to fetch") || 
         msg.includes("network error") || 
         msg.includes("load failed") ||
         msg.includes("dns_probe_finished_nxdomain");
};

export const checkConnection = async () => {
  try {
    // Teste simples na tabela profiles
    const { data, error } = await supabase
      .from('profiles')
      .select('id')
      .limit(1);

    if (error) {
      console.error("DETALHE DO ERRO DE CONEXÃO:", error);

      const msg = getErrorMessage(error);

      // Se for erro de rede real
      if (isNetworkError(error)) {
        return { ok: false, type: 'NETWORK' as const, message: msg };
      }

      // Se a tabela não existe (Erro 404 / PGRST116)
      if (error.code === 'PGRST116' || msg.includes('relation "public.profiles" does not exist')) {
          return { ok: false, type: 'SQL' as const, message: "Banco de dados online, mas tabelas não configuradas." };
      }

      // Se for erro de permissão (RLS) ou JWT, o banco está ONLINE
      if (error.status === 401 || error.status === 403 || msg.includes("JWT") || msg.includes("ApiKey")) {
          // Se for erro de chave API explicitamente
          if (msg.includes("ApiKey") || msg.includes("invalid api key")) {
              return { ok: false, type: 'AUTH_CONFIG' as const, message: "Chave API Inválida." };
          }
          return { ok: true, type: 'SUCCESS' as const };
      }

      // Qualquer outra resposta do servidor significa que ele está online
      return { ok: true, type: 'SUCCESS' as const };
    }
    return { ok: true, type: 'SUCCESS' as const };
  } catch (e: any) {
    console.error("EXCEÇÃO AO CONECTAR:", e);
    const msg = getErrorMessage(e);
    if (isNetworkError(e)) {
        return { ok: false, type: 'NETWORK' as const, message: msg };
    }
    // Se houve exceção mas não é de rede, o banco pode estar ok
    return { ok: true, type: 'SUCCESS' as const };
  }
};

