import { supabase, isNetworkError, getErrorMessage } from '../lib/supabase';

interface LoginScreenProps {
  onPublicAccess?: (module: 'FUEL') => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = ({ onPublicAccess }) => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [realEmail, setRealEmail] = useState('');
  const [password, setPassword] = useState('');
  const [sectionCode, setSectionCode] = useState(''); 
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' | 'info' | 'warning' } | null>(null);

  const ACCESS_CODE = 'FROTA5RPM'; 
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const cleanPm = pmNumber.replace(/\D/g, '');
    if (cleanPm.length < 3) {
        setMessage({ text: "Nº PM inválido.", type: 'error' });
        setLoading(false);
        return;
    }

    try {
      if (mode === 'LOGIN') {
        const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('email')
            .eq('pm_number', cleanPm) 
            .maybeSingle();

        if (profileError) {
            const errorText = getErrorMessage(profileError);
            if (isNetworkError(profileError)) {
                throw new Error(`Sem conexão com o banco. O servidor pode estar hibernando (aguarde 1 min). Erro: ${errorText}`);
            }
            throw new Error(`Erro ao validar PM: ${errorText}`);
        }

        if (!profile) {
            setMessage({ 
              text: "Nº PM não encontrado. Realize um novo cadastro.", 
              type: 'warning' 
            });
            setLoading(false);
            return;
        }

        const { error: loginError } = await supabase.auth.signInWithPassword({
          email: profile.email,
          password: password,
        });

        if (loginError) {
            const loginMsg = getErrorMessage(loginError);
            if (loginMsg.includes("Invalid login credentials")) {
                throw new Error("Senha incorreta para este Nº PM.");
            }
            throw new Error(loginMsg);
        }

      } else if (mode === 'REGISTER') {
        if (sectionCode !== ACCESS_CODE) throw new Error("Código de acesso da seção incorreto.");
        if (password.length < 6) throw new Error("A senha deve ter no mínimo 6 caracteres.");

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: realEmail,
          password: password,
          options: { data: { full_name: fullName.toUpperCase(), pm_number: cleanPm } }
        });

        if (authError) throw new Error(getErrorMessage(authError));
        setMessage({ text: "Cadastro realizado! Faça o login agora.", type: 'success' });
        setMode('LOGIN');
      } else if (mode === 'RECOVERY') {
          if (sectionCode !== ACCESS_CODE) throw new Error("Código Mestre da Seção incorreto.");
          const { error: rpcError } = await supabase.rpc('reset_password_via_pm', {
              target_pm: cleanPm,
              new_password: password,
              secret_code: sectionCode
          });
          if (rpcError) throw new Error(getErrorMessage(rpcError));
          setMessage({ text: "Senha redefinida com sucesso!", type: 'success' });
          setMode('LOGIN');
      }

    } catch (error: any) {
      setMessage({ text: getErrorMessage(error), type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex flex-col items-center justify-center p-4">
      <div className="mb-8 flex flex-col items-center">
        <img src={shieldUrl} alt="Brasão PMMG" className="h-28 mb-4 drop-shadow-xl" />
        <h1 className="text-3xl font-bold text-white text-center font-serif uppercase tracking-tight drop-shadow-md">Gestão Frota 5ª RPM</h1>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 w-full max-w-5xl items-stretch">

        {/* CARD DE ACESSO PÚBLICO (NOVO) */}
        <div className="flex-1 bg-white p-8 rounded-lg shadow-2xl border-t-8 border-blue-600 flex flex-col items-center text-center animate-fade-in order-2 lg:order-1">
          <div className="bg-blue-50 p-6 rounded-full mb-6">
            <Droplets size={48} className="text-blue-600 animate-pulse" />
          </div>
          <h2 className="text-2xl font-black text-gray-800 uppercase mb-4 tracking-tighter">Controle de Combustível</h2>
          <p className="text-gray-500 text-sm mb-8 leading-relaxed">
            Acesso público para consulta de abastecimentos e mapa de consumo da 5ª RPM. 
            <br/><span className="font-bold text-blue-700">Não exige login para visualização.</span>
          </p>

          <button 
            onClick={() => onPublicAccess?.('FUEL')}
            className="w-full mt-auto py-4 bg-blue-600 text-white font-black rounded-lg shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"
          >
            <Globe size={20} />
            Acessar Agora
          </button>
        </div>

        {/* CARD DE LOGIN RESTRITO (EXISTENTE) */}
        <div className="flex-1 bg-[#fdfbf7] p-8 rounded-lg shadow-2xl border-t-8 border-pmmg-primary animate-fade-in order-1 lg:order-2">
          <div className="text-center mb-6">
            <h2 className="text-2xl font-black text-pmmg-primary uppercase tracking-tighter">Acesso Restrito</h2>
            <p className="text-gray-400 text-[10px] uppercase font-black tracking-widest mt-1">Sistemas Internos</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Nº PM (Login)</label>
              <div className="relative">
                <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                  type="text" required
                  className="w-full pl-10 pr-4 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none tracking-widest font-mono font-bold text-gray-800 text-lg shadow-inner"
                  placeholder="123.456-7"
                  value={pmNumber}
                  onChange={(e) => {
                      let v = e.target.value.replace(/\D/g, '').slice(0, 7);
                      if (v.length > 6) v = v.replace(/^(\d{3})(\d{3})(\d)/, '$1.$2-$3');
                      else if (v.length > 3) v = v.replace(/^(\d{3})(\d)/, '$1.$2');
                      setPmNumber(v);
                  }}
                  disabled={loading}
                />
              </div>
            </div>

            {mode === 'REGISTER' && (
                <div className="animate-fade-in space-y-4">
                    <div>
                      <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Nome Completo</label>
                      <input type="text" required placeholder="POSTO/GRAD E NOME" className="w-full px-4 py-2.5 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none uppercase font-bold text-sm" value={fullName} onChange={(e) => setFullName(e.target.value.toUpperCase())} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">E-mail Pessoal</label>
                      <input type="email" required placeholder="E-MAIL PESSOAL" className="w-full px-4 py-2.5 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none text-sm" value={realEmail} onChange={(e) => setRealEmail(e.target.value)} />
                    </div>
                </div>
            )}

            {(mode === 'REGISTER' || mode === 'RECOVERY') && (
                <div className="bg-amber-50 p-4 rounded border border-amber-200">
                    <label className="block text-[10px] font-black text-amber-800 mb-1 uppercase tracking-tighter">Código Mestre da Seção</label>
                    <input type="text" required placeholder="FROTA..." className="w-full px-4 py-2 border border-amber-300 rounded focus:ring-1 focus:ring-amber-500 outline-none uppercase font-bold text-sm bg-white" value={sectionCode} onChange={(e) => setSectionCode(e.target.value.toUpperCase())} />
                </div>
            )}

            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Senha</label>
              <div className="relative">
                <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                  type={showPassword ? "text" : "password"} required
                  className="w-full pl-10 pr-10 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none shadow-inner"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  disabled={loading}
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3 text-gray-400">
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>

            {message && (
              <div className={`p-4 rounded-lg text-xs font-bold border flex items-start gap-3 ${
                  message.type === 'error' ? 'bg-red-50 text-red-800 border-red-200' : 
                  message.type === 'warning' ? 'bg-amber-50 text-amber-800 border-amber-200' :
                  'bg-green-50 text-green-800 border-green-200'
              }`}>
                {message.type === 'error' ? <XCircle size={16} className="shrink-0" /> : message.type === 'warning' ? <AlertTriangle size={16} className="shrink-0" /> : <CheckCircle size={16} className="shrink-0" />}
                <span>{message.text}</span>
              </div>
            )}

            <button
              type="submit" disabled={loading}
              className={`w-full text-white font-black py-4 rounded-lg shadow-xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest ${
                  loading ? 'bg-gray-400' : 'bg-[#3E3223] hover:bg-[#2a2218] active:scale-95'
              }`}
            >
              {loading ? <RefreshCw className="animate-spin" /> : <LogIn size={20} />}
              {mode === 'LOGIN' ? 'Entrar' : mode === 'REGISTER' ? 'Cadastrar' : 'Redefinir'}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-gray-100 text-center space-y-4">
              {mode === 'LOGIN' ? (
                  <>
                      <button onClick={() => setMode('REGISTER')} className="text-sm font-bold text-[#C5A059] hover:underline">Novo cadastro militar</button>
                      <br/>
                      <button onClick={() => setMode('RECOVERY')} className="text-xs text-gray-400 hover:text-red-500 transition-colors">Esqueceu a senha?</button>
                  </>
              ) : (
                  <button onClick={() => setMode('LOGIN')} className="text-sm font-bold text-gray-500 hover:text-[#3E3223]">Voltar ao Login</button>
              )}
          </div>
        </div>

      </div>
      <div className="mt-8 text-white/40 text-xs font-bold uppercase tracking-widest">
        © {new Date().getFullYear()} Polícia Militar de MG - 5ª RPM
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Package, Truck, History, LogOut, Home, Wifi, WifiOff, RefreshCw, Clock, AlertTriangle, ArrowRight, Settings } from 'lucide-react';
import { InventoryTab } from './components/InventoryTab';
import { MovementsTab } from './components/MovementsTab';
import { FleetTab } from './components/FleetTab';
import { checkConnection, supabase, isNetworkError, getErrorMessage } from './lib/supabase';
import { DatabaseSetup } from './components/DatabaseSetup';
import { LoginScreen } from './components/LoginScreen';
import { DashboardSelection } from './components/DashboardSelection';
import { PavModule } from './components/PavModule';
import { VehicleScheduleModule } from './components/VehicleScheduleModule';
import { FleetSubstitutionModule } from './components/FleetSubstitutionModule';
import { FuelModule } from './components/FuelModule';
import { Tab, ModuleType } from './types';

type ConnectionStatus = 'LOADING' | 'ONLINE' | 'OFFLINE_NETWORK' | 'OFFLINE_SQL' | 'OFFLINE_CONFIG';

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [connStatus, setConnStatus] = useState<ConnectionStatus>('LOADING');
  const [isRetrying, setIsRetrying] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isPublicMode, setIsPublicMode] = useState(false);

  const verifyConnection = async () => {
    setIsRetrying(true);
    const result = await checkConnection();
    if (result.ok) {
        setConnStatus('ONLINE');
    } else {
        setErrorMessage(result.message || '');
        if (result.type === 'NETWORK') setConnStatus('OFFLINE_NETWORK');
        else if (result.type === 'SQL') setConnStatus('OFFLINE_SQL');
        else if (result.type === 'AUTH_CONFIG') setConnStatus('OFFLINE_CONFIG');
    }
    setIsRetrying(false);
  };

  useEffect(() => {
    verifyConnection();
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });
    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
    setIsPublicMode(false);
  };

  const handlePublicAccess = (module: 'FUEL') => {
    setIsPublicMode(true);
    setCurrentModule(module);
  };

  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex flex-col items-center justify-center gap-4">
            <div className="w-12 h-12 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
            <div className="text-white font-bold text-xl animate-pulse uppercase tracking-widest">Sincronizando...</div>
        </div>
     );
  }

  // Se o usuário estiver em modo público, exibe apenas o módulo de combustível
  if (isPublicMode && currentModule === 'FUEL') {
      return <FuelModule isPublic={true} onBack={() => { setIsPublicMode(false); setCurrentModule(null); }} />;
  }

  if (connStatus === 'OFFLINE_CONFIG') {
      return (
        <div className="min-h-screen bg-red-900 flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-xl shadow-2xl max-w-md w-full text-center border-t-8 border-red-500">
                <Settings size={48} className="text-red-600 mx-auto mb-4 animate-spin-slow" />
                <h2 className="text-2xl font-bold text-gray-800 mb-2">Erro de Configuração</h2>
                <p className="text-gray-600 mb-6 text-sm">
                    Verifique as chaves do Supabase. Mensagem: <span className="text-red-600 font-bold">{errorMessage}</span>
                </p>
                <button onClick={() => setConnStatus('ONLINE')} className="w-full py-3 bg-gray-800 text-white font-bold rounded">Prosseguir</button>
            </div>
        </div>
      );
  }

  if (connStatus === 'OFFLINE_NETWORK') {
      return (
          <div className="min-h-screen bg-[#3E3223] flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-xl shadow-2xl max-w-md w-full text-center border-t-8 border-amber-500 animate-fade-in">
                  <div className="bg-amber-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6"><WifiOff size={40} className="text-amber-600 animate-pulse" /></div>
                  <h2 className="text-2xl font-bold text-gray-800 mb-2 font-serif">Falha de Comunicação</h2>
                  <div className="text-gray-600 mb-6 text-sm text-left bg-gray-50 p-3 rounded border">
                      <p className="font-bold text-amber-800 mb-2">O servidor não respondeu.</p>
                      <ul className="list-disc list-inside space-y-1 text-[11px]">
                          <li>O projeto Supabase pode estar hibernando.</li>
                          <li>Sua rede pode estar bloqueando a conexão.</li>
                      </ul>
                  </div>
                  <button onClick={verifyConnection} disabled={isRetrying} className="w-full py-4 bg-[#C5A059] text-[#3E3223] font-black rounded-lg shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest"><RefreshCw size={20} className={isRetrying ? 'animate-spin' : ''} /> {isRetrying ? 'Sincronizando...' : 'TENTAR NOVAMENTE'}</button>
                  <button onClick={() => setConnStatus('ONLINE')} className="w-full mt-2 py-2 text-gray-400 hover:text-gray-600 text-xs font-bold transition-colors">Ignorar e Ir ao Login</button>
              </div>
