          </p>
          <button 
            onClick={() => onPublicAccess?.('FUEL')}
            className="w-full mt-auto py-4 bg-blue-600 text-white font-black rounded-lg shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"
          >
            <Globe size={20} /> Acessar Agora
          </button>
        </div>

        {/* CARD RESTRITO: LOGIN */}
        <div className="flex-1 bg-[#fdfbf7] p-8 rounded-lg shadow-2xl border-t-8 border-[#3E3223] animate-fade-in order-1 lg:order-2">
          <div className="text-center mb-6">
            <h2 className="text-2xl font-black text-[#3E3223] uppercase tracking-tighter">Acesso Restrito</h2>
            <p className="text-gray-400 text-[10px] uppercase font-black tracking-widest mt-1">Sistemas Internos</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Nº PM (Login)</label>
              <div className="relative">
                <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                  type="text" required
                  className="w-full pl-10 pr-4 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none tracking-widest font-mono font-bold text-gray-800 text-lg shadow-inner"
                  placeholder="123.456-7"
                  value={pmNumber}
                  onChange={(e) => {
                      let v = e.target.value.replace(/\D/g, '').slice(0, 7);
                      if (v.length > 6) v = v.replace(/^(\d{3})(\d{3})(\d)/, '$1.$2-$3');
                      else if (v.length > 3) v = v.replace(/^(\d{3})(\d)/, '$1.$2');
                      setPmNumber(v);
                  }}
                  disabled={loading}
                />
              </div>
            </div>

            {mode === 'REGISTER' && (
                <div className="space-y-4 animate-fade-in">
                    <input type="text" required placeholder="NOME COMPLETO" className="w-full px-4 py-2.5 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none uppercase font-bold text-sm" value={fullName} onChange={(e) => setFullName(e.target.value.toUpperCase())} />
                    <input type="email" required placeholder="E-MAIL" className="w-full px-4 py-2.5 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none text-sm" value={realEmail} onChange={(e) => setRealEmail(e.target.value)} />
                    <input type="text" required placeholder="CÓDIGO SEÇÃO: FROTA5RPM" className="w-full px-4 py-2.5 border border-amber-300 rounded focus:ring-1 focus:ring-amber-500 outline-none uppercase font-bold text-sm bg-white" value={sectionCode} onChange={(e) => setSectionCode(e.target.value.toUpperCase())} />
                </div>
            )}

            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Senha</label>
              <div className="relative">
