              </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Material } from '../types';
import { Edit, FileDown, FileUp, AlertTriangle, Search, ArrowUpDown, ArrowUp, ArrowDown, XCircle, Filter, Check } from 'lucide-react';
import { exportToExcel, parseExcel } from '../utils/excel';

type SortKey = 'name' | 'quantity' | 'status';
type StatusType = 'NORMAL' | 'LOW' | 'NONE';

export const InventoryTab: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeFilters, setActiveFilters] = useState<StatusType[]>(['NORMAL', 'LOW', 'NONE']);
  const [search, setSearch] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'ASC' | 'DESC' }>({ key: 'name', direction: 'ASC' });
  const [isEditing, setIsEditing] = useState<Material | null>(null);
  const [formData, setFormData] = useState<Partial<Material>>({ name: '', quantity: 0, unit: 'Unidade' });

  const fetchMaterials = async () => {
    setLoading(true);
    const { data, error } = await supabase.from('materials').select('*');
    if (!error) setMaterials(data || []);
    setLoading(false);
  };

  useEffect(() => { fetchMaterials(); }, []);

  const getStatus = (m: Material): StatusType => {
    if (m.quantity <= 0) return 'NONE';
    if (m.quantity < 5) return 'LOW'; 
    return 'NORMAL';
  };

  const toggleFilter = (status: StatusType) => {
    setActiveFilters(prev => prev.includes(status) ? (prev.length > 1 ? prev.filter(s => s !== status) : prev) : [...prev, status]);
  };

  const filteredMaterials = materials
    .filter(m => {
      const status = getStatus(m);
      const matchesFilter = activeFilters.includes(status);
      const matchesSearch = m.name.toLowerCase().includes(search.toLowerCase());
      return matchesFilter && matchesSearch;
    })
    .sort((a, b) => {
      let valA: any = a[sortConfig.key as keyof Material] || '';
      let valB: any = b[sortConfig.key as keyof Material] || '';
      if (sortConfig.direction === 'ASC') return valA > valB ? 1 : -1;
      return valA < valB ? 1 : -1;
    });

  return (
    <div className="space-y-6">
      <div className="flex flex-col xl:flex-row justify-between items-center gap-4 bg-white p-4 rounded-lg shadow-sm border-l-4 border-[#3E3223]">
        <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto">
          <div className="relative w-full md:w-64">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
            <input placeholder="Buscar material..." className="w-full pl-10 pr-4 py-2 border rounded-md outline-none focus:ring-1 focus:ring-[#3E3223]" value={search} onChange={e => setSearch(e.target.value)} />
          </div>

          <div className="flex gap-2 flex-wrap">
            <button onClick={() => toggleFilter('NORMAL')} className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase flex items-center gap-1.5 border transition-all ${activeFilters.includes('NORMAL') ? 'bg-green-100 text-green-800 border-green-300' : 'bg-gray-50 text-gray-400 border-gray-200 grayscale'}`}>
              <div className="w-2 h-2 rounded-full bg-green-600"></div> Normal {activeFilters.includes('NORMAL') && <Check size={10} />}
            </button>
            <button onClick={() => toggleFilter('LOW')} className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase flex items-center gap-1.5 border transition-all ${activeFilters.includes('LOW') ? 'bg-yellow-100 text-yellow-800 border-yellow-300' : 'bg-gray-50 text-gray-400 border-gray-200 grayscale'}`}>
              <div className="w-2 h-2 rounded-full bg-yellow-600"></div> Baixo {activeFilters.includes('LOW') && <Check size={10} />}
            </button>
            <button onClick={() => toggleFilter('NONE')} className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase flex items-center gap-1.5 border transition-all ${activeFilters.includes('NONE') ? 'bg-red-100 text-red-800 border-red-300' : 'bg-gray-50 text-gray-400 border-gray-200 grayscale'}`}>
              <div className="w-2 h-2 rounded-full bg-red-600"></div> Sem Estoque {activeFilters.includes('NONE') && <Check size={10} />}
            </button>
          </div>
        </div>

        <div className="flex gap-2 w-full xl:w-auto justify-end">
          <button onClick={() => exportToExcel(materials, 'Estoque_5RPM')} className="flex items-center gap-2 px-3 py-2 bg-gray-600 text-white rounded-md text-sm"><FileDown size={16} /> Exportar</button>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-md overflow-hidden border border-gray-200">
        <table className="w-full text-left">
          <thead className="bg-gray-100 text-gray-700 text-xs uppercase">
            <tr>
              <th className="p-4 border-b">Material</th>
              <th className="p-4 border-b text-center">Qtd</th>
              <th className="p-4 border-b text-center">Unidade</th>
              <th className="p-4 border-b text-center">Status</th>
              <th className="p-4 border-b text-right">Ações</th>
            </tr>
          </thead>
          <tbody>
            {filteredMaterials.map(item => (
              <tr key={item.id} className="border-b hover:bg-amber-50">
                <td className="p-4 font-bold text-[#3E3223]">{item.name}</td>
                <td className="p-4 text-center font-mono font-bold">{item.quantity}</td>
                <td className="p-4 text-center text-gray-500">{item.unit}</td>
                <td className="p-4 text-center">
                  <span className={`px-2 py-1 rounded-full text-[10px] font-bold ${getStatus(item) === 'NORMAL' ? 'bg-green-100 text-green-800' : getStatus(item) === 'LOW' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
                    {getStatus(item)}
                  </span>
                </td>
                <td className="p-4 text-right">
                  <button onClick={() => setIsEditing(item)} className="p-2 text-gray-400 hover:text-[#3E3223]"><Edit size={16}/></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

