  if (currentModule === 'SCHEDULE') return <VehicleScheduleModule onBack={() => setCurrentModule(null)} userEmail={session?.user?.email} onLogout={handleLogout} />;
  if (currentModule === 'SUBSTITUTION') return <FleetSubstitutionModule onBack={() => setCurrentModule(null)} userEmail={session?.user?.email} onLogout={handleLogout} />;

