interface LoginScreenProps {
  onPublicAccess?: (module: 'FUEL') => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = ({ onPublicAccess }) => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [realEmail, setRealEmail] = useState('');
  const [password, setPassword] = useState('');
  const [sectionCode, setSectionCode] = useState(''); 
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' | 'info' | 'warning' } | null>(null);

  const ACCESS_CODE = 'FROTA5RPM'; 
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const cleanPm = pmNumber.replace(/\D/g, '');
    if (cleanPm.length < 3) {
        setMessage({ text: "Nº PM inválido.", type: 'error' });
        setLoading(false);
        return;
    }

    try {
      if (mode === 'LOGIN') {
        const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('email')
            .eq('pm_number', cleanPm) 
            .maybeSingle();

        if (profileError) throw new Error(getErrorMessage(profileError));
        if (!profile) {
            setMessage({ text: "Nº PM não encontrado. Realize um novo cadastro.", type: 'warning' });
            setLoading(false);
            return;
        }

        const { error: loginError } = await supabase.auth.signInWithPassword({
          email: profile.email,
          password: password,
        });

        if (loginError) {
            const loginMsg = getErrorMessage(loginError);
            if (loginMsg.includes("Invalid login credentials")) {
                throw new Error("Senha incorreta para este Nº PM.");
            }
            throw new Error(loginMsg);
        }
      } else if (mode === 'REGISTER') {
        if (sectionCode !== ACCESS_CODE) throw new Error("Código de acesso da seção incorreto.");
        const { error: authError } = await supabase.auth.signUp({
          email: realEmail,
          password: password,
          options: { data: { full_name: fullName.toUpperCase(), pm_number: cleanPm } }
        });
        if (authError) throw new Error(getErrorMessage(authError));
        setMessage({ text: "Cadastro realizado! Faça o login agora.", type: 'success' });
        setMode('LOGIN');
      }
    } catch (error: any) {
      setMessage({ text: getErrorMessage(error), type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex flex-col items-center justify-center p-4">
      <div className="mb-10 flex flex-col items-center">
        <img src={shieldUrl} alt="Brasão PMMG" className="h-32 mb-4 drop-shadow-2xl" />
        <h1 className="text-3xl font-black text-white text-center font-serif uppercase tracking-tight drop-shadow-lg">Gestão Frota 5ª RPM</h1>
      </div>

      <div className="flex flex-col lg:flex-row gap-8 w-full max-w-5xl items-stretch">
        {/* CARD PÚBLICO */}
        <div className="flex-1 bg-white p-8 rounded-xl shadow-2xl border-t-8 border-blue-600 flex flex-col items-center text-center animate-fade-in order-2 lg:order-1">
          <div className="bg-blue-50 p-6 rounded-full mb-6">
            <Droplets size={48} className="text-blue-600 animate-pulse" />
          </div>
          <h2 className="text-2xl font-black text-gray-800 uppercase mb-4 tracking-tighter">Controle de Combustível</h2>
          <p className="text-gray-500 text-sm mb-8 leading-relaxed">
            Acesso público para consulta de abastecimentos e mapa de consumo. 
            <br/><span className="font-bold text-blue-700 uppercase text-[10px] tracking-widest">Não exige login militar</span>
          </p>
          <button 
            onClick={() => onPublicAccess?.('FUEL')}
            className="w-full mt-auto py-4 bg-blue-600 text-white font-black rounded-lg shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"
          >
            <Globe size={20} /> Acessar Agora
          </button>
        </div>

        {/* CARD RESTRITO */}
        <div className="flex-1 bg-[#fdfbf7] p-8 rounded-xl shadow-2xl border-t-8 border-[#3E3223] animate-fade-in order-1 lg:order-2">
          <div className="text-center mb-6">
            <h2 className="text-2xl font-black text-[#3E3223] uppercase tracking-tighter">Acesso Restrito</h2>
            <p className="text-gray-400 text-[10px] uppercase font-black tracking-widest mt-1">Sistemas Internos</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Nº PM (Login)</label>
              <div className="relative">
                <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                  type="text" required
                  className="w-full pl-10 pr-4 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none tracking-widest font-mono font-bold text-gray-800 text-lg shadow-inner"
                  placeholder="123.456-7"
                  value={pmNumber}
                  onChange={(e) => {
                      let v = e.target.value.replace(/\D/g, '').slice(0, 7);
                      if (v.length > 6) v = v.replace(/^(\d{3})(\d{3})(\d)/, '$1.$2-$3');
                      else if (v.length > 3) v = v.replace(/^(\d{3})(\d)/, '$1.$2');
                      setPmNumber(v);
                  }}
                  disabled={loading}
                />
              </div>
            </div>

            {mode === 'REGISTER' && (
                <div className="space-y-4 animate-fade-in">
                    <input type="text" required placeholder="NOME COMPLETO" className="w-full px-4 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none uppercase font-bold text-sm" value={fullName} onChange={(e) => setFullName(e.target.value.toUpperCase())} />
                    <input type="email" required placeholder="E-MAIL" className="w-full px-4 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none text-sm" value={realEmail} onChange={(e) => setRealEmail(e.target.value)} />
                    <input type="text" required placeholder="CÓDIGO SEÇÃO" className="w-full px-4 py-3 border border-amber-300 rounded focus:ring-1 focus:ring-amber-500 outline-none uppercase font-bold text-sm bg-white" value={sectionCode} onChange={(e) => setSectionCode(e.target.value.toUpperCase())} />
                </div>
            )}

            <div>
              <label className="block text-[10px] font-black text-gray-600 mb-1 uppercase tracking-widest">Senha</label>
              <div className="relative">
                <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                  type={showPassword ? "text" : "password"} required
                  className="w-full pl-10 pr-10 py-3 border rounded-md focus:ring-2 focus:ring-[#C5A059] outline-none shadow-inner"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  disabled={loading}
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3 text-gray-400">
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>

            {message && (
              <div className={`p-4 rounded-lg text-xs font-bold border flex items-start gap-3 ${
                  message.type === 'error' ? 'bg-red-50 text-red-800 border-red-200' : 'bg-green-50 text-green-800 border-green-200'
              }`}>
                {message.type === 'error' ? <XCircle size={16} /> : <CheckCircle size={16} />}
                <span>{message.text}</span>
              </div>
            )}

            <button
              type="submit" disabled={loading}
              className={`w-full text-white font-black py-4 rounded-lg shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all ${
                  loading ? 'bg-gray-400' : 'bg-[#3E3223] hover:bg-black active:scale-95'
              }`}
            >
              {loading ? <RefreshCw className="animate-spin" /> : <LogIn size={20} />}
              {mode === 'LOGIN' ? 'Acessar' : 'Confirmar'}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-gray-100 text-center">
              <button onClick={() => setMode(mode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="text-sm font-bold text-[#C5A059] hover:underline">
                {mode === 'LOGIN' ? 'Não possui conta? Registre-se aqui.' : 'Voltar para o Login'}
              </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Material } from '../types';
import { Edit, FileDown, FileUp, AlertTriangle, Search, ArrowUpDown, ArrowUp, ArrowDown, XCircle, Filter, Check } from 'lucide-react';
import { exportToExcel, parseExcel } from '../utils/excel';

type SortKey = 'name' | 'quantity' | 'status';
type StatusType = 'NORMAL' | 'LOW' | 'NONE';

export const InventoryTab: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeFilters, setActiveFilters] = useState<StatusType[]>(['NORMAL', 'LOW', 'NONE']);
  const [search, setSearch] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'ASC' | 'DESC' }>({ key: 'name', direction: 'ASC' });
  const [isEditing, setIsEditing] = useState<Material | null>(null);
  const [formData, setFormData] = useState<Partial<Material>>({ name: '', quantity: 0, unit: 'Unidade' });

  const fetchMaterials = async () => {
    setLoading(true);
    const { data, error } = await supabase.from('materials').select('*');
    if (!error) setMaterials(data || []);
    setLoading(false);
  };

  useEffect(() => { fetchMaterials(); }, []);

  const getStatus = (m: Material): StatusType => {
    if (m.quantity <= 0) return 'NONE';
    if (m.quantity < 5) return 'LOW'; 
    return 'NORMAL';
  };

  const toggleFilter = (status: StatusType) => {
    setActiveFilters(prev => 
      prev.includes(status) 
        ? (prev.length > 1 ? prev.filter(s => s !== status) : prev) 
        : [...prev, status]
    );
  };

  const filteredMaterials = materials
    .filter(m => {
      const status = getStatus(m);
      const matchesFilter = activeFilters.includes(status);
      const matchesSearch = m.name.toLowerCase().includes(search.toLowerCase());
      return matchesFilter && matchesSearch;
    })
    .sort((a, b) => {
      let valA: any = a[sortConfig.key as keyof Material] || '';
      let valB: any = b[sortConfig.key as keyof Material] || '';
      if (sortConfig.direction === 'ASC') return valA > valB ? 1 : -1;
      return valA < valB ? 1 : -1;
    });

  return (
    <div className="space-y-6">
      <div className="flex flex-col xl:flex-row justify-between items-center gap-4 bg-white p-4 rounded-lg shadow-sm border-l-4 border-[#3E3223]">
        <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto">
          <div className="relative w-full md:w-64">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
            <input 
              placeholder="Buscar material..." 
              className="w-full pl-10 pr-4 py-2 border rounded-md outline-none focus:ring-1 focus:ring-[#3E3223]" 
              value={search} 
              onChange={e => setSearch(e.target.value)} 
            />
          </div>

          <div className="flex gap-2 flex-wrap items-center">
            <span className="text-[10px] font-black uppercase text-gray-400 mr-2 flex items-center gap-1"><Filter size={12}/> Exibir:</span>
            <button 
              onClick={() => toggleFilter('NORMAL')} 
