  return (
    <div className="min-h-screen bg-[#958458] flex flex-col font-sans">
      <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentModule(null)} className="text-[#C5A059] bg-white/5 p-2 rounded hover:bg-white/10 flex flex-col items-center">
              <Home size={20} /> <span className="text-[10px] font-bold uppercase mt-1">Menu</span>
            </button>
            <img src={shieldUrl} alt="Escudo" className="h-24" />
          </div>
          <div className="text-right">
            <h1 className="text-2xl md:text-3xl font-extrabold text-[#C5A059] uppercase tracking-tight">Estoque 5ª RPM</h1>
            <div className="text-white/80 text-xs font-bold mt-1 flex items-center justify-end gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div> {session?.user?.user_metadata?.full_name || session?.user?.email}
            </div>
          </div>
        </div>
        <div className="bg-[#4A3B2A]/90 backdrop-blur-sm text-white/90">
          <div className="container mx-auto px-4 flex justify-between items-center overflow-x-auto">
            <div className="flex gap-1">
              <button onClick={() => setActiveTab('inventory')} className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase text-sm ${activeTab === 'inventory' ? 'border-[#C5A059] text-[#C5A059] bg-black/20' : 'border-transparent text-white/70 hover:text-white'}`}><Package size={18} /> Estoque</button>
              <button onClick={() => setActiveTab('movements')} className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase text-sm ${activeTab === 'movements' ? 'border-[#C5A059] text-[#C5A059] bg-black/20' : 'border-transparent text-white/70 hover:text-white'}`}><History size={18} /> Movimentações</button>
              <button onClick={() => setActiveTab('fleet')} className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase text-sm ${activeTab === 'fleet' ? 'border-[#C5A059] text-[#C5A059] bg-black/20' : 'border-transparent text-white/70 hover:text-white'}`}><Truck size={18} /> Mapa Carga</button>
