                      {isRetrying ? 'Tentando...' : 'Reconectar'}
                  </button>
              </div>
          </div>
      );
  }

  if (connStatus === 'OFFLINE_SQL') {
      return <DatabaseSetup onBack={() => verifyConnection()} />;
