                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-gray-400 mb-1 block">Data Solic. O.S. *</label>
                  <input type="date" className={`w-full border p-2 rounded text-sm outline-none focus:ring-1 focus:ring-blue-400 ${errors.os_request_date && 'border-red-500'}`} value={formData.os_request_date} onChange={e => setFormData({...formData, os_request_date: e.target.value})} />
                </div>
              </div>

              <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-100">
                <input type="checkbox" id="sent" className="w-5 h-5 accent-[#C5A059] cursor-pointer" checked={formData.sent_to_inquirer} onChange={e => setFormData({...formData, sent_to_inquirer: e.target.checked})} />
                <label htmlFor="sent" className="text-sm font-bold text-gray-700 cursor-pointer flex items-center gap-2 select-none">
                  {formData.sent_to_inquirer ? <CheckCircle size={16} className="text-green-600"/> : <XCircle size={16} className="text-red-400"/>}
                  Processo enviado para o Encarregado
                </label>
              </div>

              <div>
                <label className="text-[10px] font-black uppercase text-gray-500 mb-1 block tracking-wider">Observações / Pendências</label>
                <textarea className="w-full border p-3 rounded text-sm outline-none focus:ring-1 focus:ring-[#C5A059] h-24 resize-none shadow-inner" value={formData.observations} onChange={e => setFormData({...formData, observations: e.target.value})} placeholder="Detalhes adicionais sobre o andamento..." />
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 flex justify-end gap-3 rounded-b-xl shadow-inner">
              <button onClick={() => setIsModalOpen(false)} className="px-8 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-bold border border-gray-300 transition-all uppercase text-xs tracking-widest">Cancelar</button>
              <button onClick={handleSave} className="px-10 py-2.5 bg-[#3E3223] text-[#C5A059] rounded-lg font-black uppercase tracking-widest shadow-lg hover:bg-black transition-all">Salvar Processo</button>
            </div>
          </div>
        </div>
      )}

      {deletingId && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-sm border-t-8 border-red-600 animate-fade-in text-center">
            <AlertTriangle size={48} className="text-red-600 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-gray-800 mb-2 uppercase">Confirmar Exclusão</h3>
            <p className="text-gray-600 mb-8 text-sm">Deseja realmente apagar este registro de PAV? Esta ação não pode ser desfeita.</p>
            <div className="flex justify-center gap-4">
              <button onClick={() => setDeletingId(null)} className="px-6 py-2 text-gray-500 font-bold border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors uppercase text-xs">Cancelar</button>
              <button onClick={confirmDelete} className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 shadow-lg transition-colors uppercase text-xs">Sim, Excluir</button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f1f1; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #C5A059; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #3E3223; }
        @keyframes fade-in { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
