    vehicle_prefix: '',
    start_date: '',
    end_date: '',
    start_hour: '',
    end_hour: '',
    driver_name: '',
    reason: '',
    observations: ''
  };
  const [formData, setFormData] = useState(initialForm);

  const fetchData = async () => {
    setLoading(true);
    const { data: sch } = await supabase.from('vehicle_schedules').select('*').order('start_time', { ascending: true });
    const { data: vtr } = await supabase.from('vehicles').select('*').order('prefix');
    if (sch) setSchedules(sch);
    if (vtr) setVehicles(vtr);
    setLoading(false);
  };

  useEffect(() => { fetchData(); }, []);

  const checkConflict = (newStart: Date, newEnd: Date, prefix: string, excludeId?: string): VehicleSchedule | null => {
    const vehicleSchedules = schedules.filter(s => s.vehicle_prefix === prefix);
    for (const schedule of vehicleSchedules) {
        if (excludeId && schedule.id === excludeId) continue;
        const existingStart = new Date(schedule.start_time);
        const existingEnd = new Date(schedule.end_time);
        if (newStart < existingEnd && newEnd > existingStart) return schedule;
    }
    return null;
  };

  const handleSaveSchedule = async (forceSave: boolean = false) => {
    setConflictError(null);
    setErrorMessage(null);

    if (!formData.vehicle_prefix || !formData.driver_name || !formData.reason || !formData.start_hour || !formData.end_hour) {
      setErrorMessage("Preencha todos os campos obrigatórios.");
      return;
    }

    const schedulesToInsert: any[] = [];
    if (isMultiDayMode) {
        if (multiDates.length === 0) { setErrorMessage("Adicione pelo menos uma data."); return; }
        for (const dateStr of multiDates) {
            const currentStart = new Date(`${dateStr}T${formData.start_hour}:00`);
            let currentEnd = new Date(`${dateStr}T${formData.end_hour}:00`);
            if (currentEnd <= currentStart) currentEnd.setDate(currentEnd.getDate() + 1);
            if (!forceSave) {
                const conflict = checkConflict(currentStart, currentEnd, formData.vehicle_prefix);
                if (conflict) {
                  setConflictError(
                    <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-4 rounded flex flex-col gap-2">
                      <div className="font-bold text-red-700 uppercase flex items-center gap-2"><AlertCircle size={16}/> CONFLITO EM {new Date(dateStr).toLocaleDateString()}</div>
                      <button onClick={() => handleSaveSchedule(true)} className="bg-red-600 text-white px-4 py-1.5 rounded text-[10px] font-black w-fit uppercase">Ignorar e Salvar Mesmo Assim</button>
                    </div>
                  );
                  return;
                }
            }
            schedulesToInsert.push({ vehicle_prefix: formData.vehicle_prefix, driver_name: formData.driver_name.toUpperCase(), reason: formData.reason.toUpperCase(), start_time: currentStart.toISOString(), end_time: currentEnd.toISOString(), observations: formData.observations });
        }
    } else {
        const start = new Date(`${formData.start_date}T${formData.start_hour}:00`);
        const end = new Date(`${formData.end_date}T${formData.end_hour}:00`);
        if (end <= start) { setErrorMessage("Horário de retorno deve ser após o de saída."); return; }
        if (!forceSave) {
          const conflict = checkConflict(start, end, formData.vehicle_prefix, editingScheduleId || undefined);
          if (conflict) {
            setConflictError(
              <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-4 rounded flex flex-col gap-2">
                <div className="font-bold text-red-700 uppercase flex items-center gap-2"><AlertCircle size={16}/> CONFLITO DETECTADO</div>
                <button onClick={() => handleSaveSchedule(true)} className="bg-red-600 text-white px-4 py-1.5 rounded text-[10px] font-black w-fit uppercase">Ignorar e Salvar Mesmo Assim</button>
              </div>
            );
            return;
          }
        }
        schedulesToInsert.push({ vehicle_prefix: formData.vehicle_prefix, driver_name: formData.driver_name.toUpperCase(), reason: formData.reason.toUpperCase(), start_time: start.toISOString(), end_time: end.toISOString(), observations: formData.observations });
    }

    try {
        if (editingScheduleId && !isMultiDayMode) {
          await supabase.from('vehicle_schedules').update(schedulesToInsert[0]).eq('id', editingScheduleId);
        } else {
          await supabase.from('vehicle_schedules').insert(schedulesToInsert);
        }
        setIsModalOpen(false);
        fetchData();
    } catch (e) { alert("Erro ao salvar agendamento."); }
  };

  const confirmDelete = async () => {
    if (!deletingId) return;
    await supabase.from('vehicle_schedules').delete().eq('id', deletingId);
    setDeletingId(null);
    fetchData();
  };

  const toggleSelection = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const batchDelete = async () => {
    if (!confirm(`Excluir ${selectedIds.length} agendamentos?`)) return;
    await supabase.from('vehicle_schedules').delete().in('id', selectedIds);
    setSelectedIds([]);
    setIsSelectionMode(false);
    fetchData();
  };

  const filtered = schedules.filter(s => {
      const match = s.vehicle_prefix.includes(search) || s.driver_name.toLowerCase().includes(search.toLowerCase());
      const isFuture = new Date(s.end_time) > new Date();
      return match && (viewMode === 'ALL' || isFuture);
  });

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
       <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">
          <div className="flex items-center gap-4 py-2">
             <button onClick={onBack} className="flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg"><Home size={20} /><span className="text-[10px] uppercase font-bold mt-1">Menu</span></button>
             <img src={shieldUrl} alt="Escudo" className="h-28 drop-shadow-xl" />
          </div>
          <div className="text-right">
             <h1 className="text-3xl md:text-4xl font-extrabold tracking-tight text-[#C5A059] font-serif uppercase">AGENDA DE VIATURA</h1>
             <p className="text-lg font-bold text-[#C5A059] opacity-90 tracking-widest font-serif">FROTA 5ª RPM</p>
             <div className="mt-2 text-right">
                <span className="text-sm font-bold text-white uppercase tracking-wider">BEM-VINDO, {userEmail.toUpperCase()}</span>
             </div>
          </div>
        </div>
        <div className="bg-[#4A3B2A]/90 backdrop-blur-sm text-white/90 py-2"><div className="container mx-auto px-4 flex justify-end items-center"><button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 text-red-200 hover:text-red-100 hover:bg-red-900/30 rounded transition-colors text-sm font-semibold"><LogOut size={18} /> Sair</button></div></div>
      </header>

      <main className="container mx-auto px-4 py-8 flex-grow pb-24">
        <div className="bg-[#fdfbf7] rounded-xl shadow-2xl border border-[#d4c5a3] p-6 min-h-[600px]">
          <div className="flex flex-col xl:flex-row justify-between items-center gap-4 mb-8">
            <div className="flex flex-wrap gap-3 w-full xl:w-auto">
                <div className="relative w-full sm:w-64"><Search className="absolute left-3 top-2.5 text-gray-400" size={18}/><input type="text" placeholder="Buscar por prefixo ou motorista..." className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-1 focus:ring-[#C5A059] outline-none text-sm" value={search} onChange={e => setSearch(e.target.value)} /></div>
                <select className="border rounded-lg px-3 py-2 text-sm font-bold bg-white" value={viewMode} onChange={e => setViewMode(e.target.value as any)}><option value="FUTURE">Agendamentos Futuros</option><option value="ALL">Todos os Registros</option></select>
                <button onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds([]); }} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold border transition-all ${isSelectionMode ? 'bg-orange-600 text-white border-orange-700' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}><MousePointerClick size={16}/> {isSelectionMode ? 'Sair Seleção' : 'Selecionar Vários'}</button>
                {isSelectionMode && selectedIds.length > 0 && <button onClick={batchDelete} className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm font-black uppercase tracking-wider flex items-center gap-2 animate-bounce"><Trash2 size={16}/> Excluir ({selectedIds.length})</button>}
            </div>
            <button onClick={() => { setFormData(initialForm); setEditingScheduleId(null); setIsMultiDayMode(false); setIsModalOpen(true); }} className="bg-[#C5A059] text-[#3E3223] font-black py-2.5 px-8 rounded-lg shadow-lg uppercase tracking-wider flex items-center gap-2 hover:bg-[#B08D4A] transition-all w-full sm:w-auto justify-center"><Plus size={20}/> Novo Agendamento</button>
