             filtered.map(s => (
                <div key={s.id} onClick={() => isSelectionMode && toggleSelection(s.id)} className={`bg-white p-5 rounded-lg border shadow-sm relative group hover:shadow-md transition-all cursor-pointer ${selectedIds.includes(s.id) ? 'ring-2 ring-orange-500 border-orange-500 bg-orange-50' : 'border-gray-100'}`}>
                    <div className="flex items-center justify-between mb-4">
