                    </div>
                    <div className="space-y-2 mb-4">
                        <div className="flex items-center gap-2 text-lg font-bold text-gray-700"><Calendar size={20} className="text-[#C5A059]"/> {new Date(s.start_time).toLocaleDateString('pt-BR')} <span className="text-gray-400 ml-1">{new Date(s.start_time).toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})}</span></div>
                        <div className="text-[10px] text-gray-400 font-black ml-7 uppercase tracking-widest">até</div>
                        <div className="flex items-center gap-2 text-lg font-bold text-gray-700"><Calendar size={20} className="text-[#C5A059]"/> {new Date(s.end_time).toLocaleDateString('pt-BR')} <span className="text-gray-400 ml-1">{new Date(s.end_time).toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})}</span></div>
