                    <div className="text-xs font-black uppercase text-gray-800 mb-2 border-t pt-4 flex items-center gap-2"><User size={16} className="text-gray-400"/> {s.driver_name}</div>
                    <div className="bg-gray-50 p-3 rounded-lg text-xs font-bold text-gray-600 uppercase italic border border-gray-100">Motivo: {s.reason}</div>
                    {!isSelectionMode && (
                        <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => { e.stopPropagation(); setEditingScheduleId(s.id); setFormData({...s as any, start_date: s.start_time.split('T')[0], start_hour: new Date(s.start_time).toTimeString().slice(0,5), end_date: s.end_time.split('T')[0], end_hour: new Date(s.end_time).toTimeString().slice(0,5)}); setIsMultiDayMode(false); setIsModalOpen(true); }} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Edit size={18}/></button>
                            <button onClick={(e) => { e.stopPropagation(); setDeletingId(s.id); }} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 size={18}/></button>
                        </div>
                    )}
                </div>
            ))}
          </div>
