                    </div>
                    <div className="flex flex-wrap gap-2 mb-4">
                      {multiDates.map(d => (
                        <div key={d} className="bg-white px-3 py-1.5 rounded-full text-[10px] font-black text-indigo-800 border border-indigo-200 flex items-center gap-2">
