  const initialForm = {
    fraction: '',
    vehicle_prefix: '',
    vehicle_plate: '',
    accident_date: '',
    reds_number: '',
    pav_number: '',
    inquirer: '',
    inquirer_pm_number: '', // Novo campo
    sent_to_inquirer: false,
    os_request_date: '',
    os_number: '',
    os_followup_date: '',
    observations: ''
  };
