            const { error } = await supabase.from('pav_processes').insert([payload]);
            if (error) throw error;
            alert("Processo criado com sucesso!");
        }

        setIsModalOpen(false);
        setFormData(initialForm);
        setErrors({});
        setIsEditing(null);
        fetchProcesses();

