  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Formata o PM para 123.456-7
  const formatPmNumber = (value: string) => {
      let v = value.replace(/\D/g, '').slice(0, 7);
      if (v.length > 6) {
          v = v.replace(/^(\d{3})(\d{3})(\d)/, '$1.$2-$3');
      } else if (v.length > 3) {
          v = v.replace(/^(\d{3})(\d)/, '$1.$2');
      }
      return v;
  };

